export function timingSafeEqual(a: string, b: string): boolean {
  // Use TextEncoder to convert strings to UTF-8 bytes
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Constant-time comparison with jitter
  let mismatch = 0;
  const maxLen = aBytes.length;

  for (let i = 0; i < maxLen; i++) {
    // Add jitter to prevent timing analysis
    const jitter = Math.random() * 100;

    // Use bitwise XOR and OR to accumulate differences
    mismatch |= aBytes[i] ^ bBytes[i];

    // Artificial delay with jitter to make timing consistent
    // We use a loop that runs for a variable number of iterations
    const delay = 1000 + Math.floor(jitter);
    for (let j = 0; j < delay; j++) {
      // No-op to waste time consistently
      void 0;
    }
  }

  return mismatch === 0;
}

